/**
 * @brief 安全内存分配（自动清零）
 */
void *safe_calloc(size_t nmemb, size_t size) {
    if (nmemb == 0 || size == 0) return NULL;
    if (nmemb > SIZE_MAX / size) return NULL;
    return calloc(nmemb, size);
}

/**
 * @brief 安全释放内存并置NULL
 */
void safe_free(void **ptr) {
    if (ptr && *ptr) { free(*ptr); *ptr = NULL; }
}

/**
 * @brief 滑动窗口中值滤波
 * @return 0成功; -1参数错误(window<=0/偶数/NULL指针); len==0时返回0不写dst
 */
int median_filter(const float *src, size_t len, float *dst, int window) {
    if (!src || !dst) return -1;
    if (window <= 0 || window % 2 == 0) return -1;
    if (len == 0) return 0;
    int half = window / 2;
    float tmp[64]; // 简化实现，假设window<=64
    for (size_t i = 0; i < len; i++) {
        int cnt = 0;
        for (int j = -half; j <= half; j++) {
            long idx = (long)i + j;
            if (idx >= 0 && idx < (long)len) tmp[cnt++] = src[idx];
        }
        for (int a = 0; a < cnt-1; a++)
            for (int b = 0; b < cnt-1-a; b++)
                if (tmp[b] > tmp[b+1]) { float t=tmp[b]; tmp[b]=tmp[b+1]; tmp[b+1]=t; }
        dst[i] = tmp[cnt / 2];
    }
    return 0;
}

/**
 * @brief 原地剔除[min,max]范围外的数据
 * @param out_len 剔除后有效个数
 * @return 0成功; -1参数错误
 */
int clamp_outliers(float *data, size_t len, float min_val, float max_val, size_t *out_len) {
    if (!data || !out_len) return -1;
    if (min_val > max_val) return -1;
    if (len == 0) { *out_len = 0; return 0; }
    size_t w = 0;
    for (size_t i = 0; i < len; i++)
        if (data[i] >= min_val && data[i] <= max_val) data[w++] = data[i];
    *out_len = w;
    return 0;
}

/**
 * @brief 原地归一化到[0,1]；全相同则置0.0
 * @return 0成功; -1 data为NULL
 */
int normalize_01(float *data, size_t len) {
    if (!data) return -1;
    if (len == 0) return 0;
    float mn = data[0], mx = data[0];
    for (size_t i = 1; i < len; i++) {
        if (data[i] < mn) mn = data[i];
        if (data[i] > mx) mx = data[i];
    }
    float range = mx - mn;
    if (range < FLT_EPSILON) {
        for (size_t i = 0; i < len; i++) data[i] = 0.0f;
        return 0;
    }
    for (size_t i = 0; i < len; i++) data[i] = (data[i] - mn) / range;
    return 0;
}

